<?phpnamespace app\api\controller;use app\api\model\Setting as SettingModel;/** * 商户配置 */class Setting extends Controller{    /**     * 订阅消息配置	 * $order_mode 订单类型     */    public function tpl($order_mode,$table_id=0)    {        $tpl = [];		if($values = SettingModel::getItem('wxapptpl')){    		if($order_mode == 'pact'){    			array_push($tpl,$values['pact_status']);//预约状态提醒    		}elseif($order_mode == 'refund'){    			array_push($tpl,$values['refund']);//退款状态提醒    		}elseif($order_mode == 20){    		    //如果是外卖    			array_push($tpl,$values['receive']);//商家接单    			array_push($tpl,$values['horseman']);//骑手取餐    			array_push($tpl,$values['delivery']);//订单配送    		}else{    		    array_push($tpl,$values['receive']);//商家接单    			$table_id == 0 && array_push($tpl,$values['take']);//取餐提醒    		}		}		return $this->renderSuccess($tpl);    }        /**     * 获取wifi配置     */    public function wifi()    {        $values = SettingModel::getItem('wifi');		return $this->renderSuccess($values);    }}